/*
 * Copyright 2026 Overclock Validator
 * SPDX-License-Identifier: Apache-2.0
 *
 * Immutable radix-256 basepoint-comb payload.
 *
 * The binary is generated by tools/generate_fixed_base_comb.py using Python
 * big-integer affine Edwards arithmetic.  Its format and checksum are
 * documented in docs/architecture/FIXED_BASE_COMB.md.  Keeping the 480 KiB
 * table as binary data avoids 61,440 hand-unreviewable .quad directives while
 * leaving the exact payload reproducible and process-shared.
 */
.section .rodata
.p2align 6
.globl narya_fixed_base_comb_r256
.hidden narya_fixed_base_comb_r256
.type narya_fixed_base_comb_r256, @object
narya_fixed_base_comb_r256:
.incbin "data/narya_fixed_base_comb_r256.bin"
.size narya_fixed_base_comb_r256, .-narya_fixed_base_comb_r256

/*
 * One-row signed width-10 table: [1]B through [512]B. It is consumed by the
 * merged cold double-scalar schedule, which reuses the variable-base term's
 * existing 250 doublings instead of running the two-row comb separately.
 */
.p2align 6
.globl narya_fixed_base_b10
.hidden narya_fixed_base_b10
.type narya_fixed_base_b10, @object
narya_fixed_base_b10:
.incbin "data/narya_fixed_base_b10.bin"
.size narya_fixed_base_b10, .-narya_fixed_base_b10

/*
 * Coordinate-parallel width-8 NAF table for the singleton verifier. Each
 * 160-byte entry is one positive odd multiple in five [Y-X,Y+X,2dT,2Z]
 * rows. The independent affine generator is
 * tools/generate_packed_naf_basepoint.py.
 */
.p2align 6
.globl narya_packed_naf_basepoint
.hidden narya_packed_naf_basepoint
.type narya_packed_naf_basepoint, @object
narya_packed_naf_basepoint:
.incbin "data/narya_packed_naf_basepoint.bin"
.size narya_packed_naf_basepoint, .-narya_packed_naf_basepoint

.section .note.GNU-stack,"",@progbits
